# NOT PLANTED
# - 'a second part of four is preferred' (`for length in [4, 5]`): the same rule. A part of five
#   that no letter follows cannot also be a part of four that no letter follows, so at most one
#   of the two lengths matches and their order cannot be seen.
# - The OpenCode server's start bound (`STARTING`, 30 s) and end bound (`ENDING`, 10 s): a test that
#   waits for either is a test of minutes; the stand-in announces itself and ends on its signal.
# - The probe's version (`serve::version`): kept beside the methods and read by nothing.
if __name__ == '__main__':
    raise SystemExit(runner.main(__file__, RUNS, PLANTS))
